const paths={home:'خانه',ads:'کاوش تبلیغات',products:'محصولات',shops:'فروشگاه‌ها',reports:'گزارش و تحلیل',saved:'ذخیره‌شده‌ها'},hashes={portal:'#/',start:'#/start/idea',home:'#/workspace/home',ads:'#/workspace/ads',products:'#/workspace/products',shops:'#/workspace/shops',reports:'#/workspace/overview',saved:'#/workspace/saved'};
const initial=()=>({workspace:'فضای کار آریا',theme:'light',filters:{},sort:{ads:'reach',products:'recent',shops:'growth'},view:{ads:'grid',products:'list',shops:'table'},saved:{ads:[],products:[],shops:[]},alerts:[],compared:[],customShops:[],reports:[],pagination:{},topTab:'ads',savedTab:'ads',day:4,period:30,scope:'all',shopMode:'all',onePerShop:false,reportType:'ads'});
let state;try{const stored=JSON.parse(localStorage.getItem(STORE)||'null');state={...initial(),...stored,saved:{...initial().saved,...stored?.saved},view:{...initial().view,...stored?.view},sort:{...initial().sort,...stored?.sort}}}catch{state=initial()}
