function media(key,alt='',extra=''){const m=D.media[key]||D.media.fashion;return `<span class="media ${extra}" role="img" aria-label="${esc(alt||'تصویر مرجع محصول')}">${m.sw?`<svg viewBox="${m.x} ${m.y} ${m.w} ${m.h}" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><image href="${m.src}" width="${m.sw}" height="${m.sh}"/></svg>`:`<img src="${m.src}" alt="" loading="lazy">`}</span>`}
const initials=s=>`<span class="shop-initial" style="background:${/^#[a-f\d]{6}$/i.test(s.color)?s.color:'#f0e9ed'}">${esc(s.initial||s.name.slice(0,1))}</span>`;
const saved=(type,id)=>state.saved[type].includes(id),saveButton=(type,id,label='')=>`<button type="button" class="icon-btn" data-save="${type}" data-id="${id}" aria-pressed="${saved(type,id)}" aria-label="${esc(label||'ذخیرهٔ '+(type==='ads'?'تبلیغ':type==='products'?'محصول':'فروشگاه'))}" title="ذخیره">${ico('bookmark')}</button>`;
function spark(values,large=false,label='روند رشد نمونه'){if(!values?.length)return'<span class="muted">در انتظار داده</span>';const max=Math.max(...values)*1.07,min=Math.min(...values)*.8,points=values.map((v,i)=>`${(i/(values.length-1)*160).toFixed(1)},${(50-(v-min)/(max-min)*45).toFixed(1)}`).join(' ');return `<svg class="sparkline" viewBox="0 0 160 55" preserveAspectRatio="none" role="img" aria-label="${esc(label)}"><polygon points="0,55 ${points} 160,55" fill="var(--chart-area)"/><polyline points="${points}" fill="none" stroke="var(--chart)" stroke-width="${large?1.8:1.6}" vector-effect="non-scaling-stroke"/></svg>`}
function thumb(key,type,id,play=false){return`<button type="button" class="mini-thumb" data-open="${type}" data-id="${id}" aria-label="${type==='ads'?'نمایش تبلیغ مرتبط':'نمایش محصول مرتبط'}">${media(key)}${play?ico('play'):''}</button>`}
function platform(a){return `<span class="platform ${a.platform.toLowerCase()}">${ico(a.platform==='Meta'?'meta':a.platform==='YouTube'?'play':'ads')}<b>${a.platform==='Meta'?'Meta':a.platform==='TikTok'?'TikTok':'YouTube'}</b></span>`}
function headerTitle(){return paths[page]||paths.home}
function shell(content){const f=F(['ads','products','shops'].includes(page)?page:'ads');return`<a class="skip" href="#content">رفتن به محتوای صفحه</a>${mobileMenu?'<div class="sidebar-backdrop" data-action="mobile-menu"></div>':''}<aside class="sidebar ${mobileMenu?'open':''}" aria-label="راهبری Analyze"><a class="brand" href="${hashes.home}" aria-label="نما، خانه"><img src="assets/mark.svg" alt=""><span><strong>NAMA</strong><small>ANALYZE / INTELLIGENCE</small></span></a>${act(`<span class="workspace-icon">آ</span><span class="grow">${esc(state.workspace)}</span>${ico('down')}`,'workspace','workspace-picker','aria-label="تنظیم فضای کاری"')}<span class="nav-label">فضای تحلیل</span><nav class="nav">${[['home','home','خانه','Home'],['ads','ads','تبلیغات','Ads'],['products','product','محصولات','Products'],['shops','shop','فروشگاه‌ها','Shops']].map(([key,icon,label,en])=>`<a class="nav-link ${page===key?'active':''}" href="${hashes[key]}" ${page===key?'aria-current="page"':''}>${ico(icon)}<span>${label}</span><span class="latin">${en}</span></a>${key==='shops'&&page==='shops'?`<div class="subnav"><a href="${hashes.shops}" data-shop-mode="all" class="${state.shopMode==='all'?'active':''}">فروشگاه‌های رو به رشد</a><a href="${hashes.shops}" data-shop-mode="tracked" class="${state.shopMode==='tracked'?'active':''}">فروشگاه‌های پیگیری‌شده <span class="pill">${fa(state.saved.shops.length)}</span></a></div>`:''}`).join('')}<div class="nav-separator"></div>${[['reports','chart','گزارش و تحلیل','Reports'],['saved','bookmark','ذخیره‌شده‌ها','Saved']].map(([key,icon,label,en])=>`<a class="nav-link ${page===key?'active':''}" href="${hashes[key]}" ${page===key?'aria-current="page"':''}>${ico(icon)}<span>${label}</span><span class="latin">${en}</span></a>`).join('')}</nav><div class="nav-separator"></div><span class="nav-label">گزارش‌های من</span>${state.reports.slice(-3).reverse().map(r=>`<button class="report-link" data-action="open-report" data-id="${r.id}">${ico('file')}${esc(r.name)}</button>`).join('')||`<button class="report-link" data-action="new-report">${ico('plus')}ساخت اولین گزارش</button>`}<div class="side-spacer"></div><div class="side-callout"><h3>روشن‌تر ببین. بهتر تصمیم بگیر.</h3><p>تبلیغ، محصول و فروشگاه را در کنار هم بررسی کن.</p><a href="${hashes.reports}">نمای کلی بازار ${ico('arrow')}</a></div><div class="profile"><span class="avatar">آ</span><span>آریا حسن‌زاده<small>فضای شخصی · دموی طراحی</small></span>${act(ico('more'),'profile-menu','icon-btn','aria-label="تنظیمات دمو"')}</div></aside><div class="workspace"><header class="topbar">${act(ico('menu'),'mobile-menu','icon-btn mobile-toggle','aria-label="بازکردن منو"')}<div class="breadcrumbs"><span class="latin">Analyze</span><span>/</span><strong>${headerTitle()}</strong></div><form class="header-search" data-form="header-search">${ico('search')}<label class="sr-only" for="headerQuery">جست‌وجو در نما</label><input id="headerQuery" type="search" placeholder="جست‌وجوی تبلیغ، محصول یا فروشگاه..." value="${esc(['ads','products','shops'].includes(page)?f.query||'':'')}" autocomplete="off"><kbd>⌘ K</kbd></form><div class="top-actions"><span class="badge">نسخهٔ نمایشی</span>${act(ico(state.theme==='dark'?'sun':'moon'),'theme','icon-btn','aria-label="تغییر تم"')}${act(ico('bell'),'notifications','icon-btn','aria-label="اعلان‌ها"')}${act(ico('plus')+'<span class="new-report-label">گزارش جدید</span>','new-report','btn primary')}</div></header><main class="content" id="content" tabindex="-1">${content}<footer class="page-footer"><span><span class="dot" style="color:var(--red)"></span> داده‌ها، رشد و درآمدهای این دمو نمونه‌اند؛ پژوهش زنده انجام نمی‌شود.</span><span class="latin">NAMA / ANALYZE ONLY</span></footer></main></div>${state.compared.length?`<div class="comparison-bar"><span>${fa(state.compared.length)} تبلیغ برای مقایسه انتخاب شده</span>${act('مقایسهٔ انتخاب‌ها','compare','btn primary')}${act(ico('close'),'clear-compare','icon-btn','aria-label="پاک‌کردن مقایسه"')}</div>`:''}`}
function head(title,desc,eyebrow,actions=''){return`<section class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></section>`}
function sectionHead(title,desc,link='',label='دیدن همه'){return`<div class="section-head"><div><h2>${title}</h2><p>${desc}</p></div>${link?`<a class="btn" href="${hashes[link]}">${label}${ico('arrow')}</a>`:''}</div>`}
function options(values,current,empty='همهٔ موارد'){return`<option value="">${empty}</option>`+values.map(v=>{const [val,label]=Array.isArray(v)?v:[v,v];return`<option value="${esc(val)}" ${String(current)===String(val)?'selected':''}>${esc(label)}</option>`}).join('')}
function filterControl(key,icon,values,label,p=page){const f=F(p);return`<label class="filter">${ico(icon)}<span class="sr-only">${label}</span><select aria-label="${label}" data-filter="${key}" data-page="${p}" data-value="${esc(f[key]||'')}">${options(values,f[key],label)}</select></label>`}
function sortSelect(p=page){return`<select class="sort-select" aria-label="مرتب‌سازی" data-control="sort" data-page="${p}">${options(p==='ads'?[['reach','بیشترین بازدید'],['roas','بالاترین ROAS'],['active','بیشترین روز فعالیت'],['recent','جدیدترین']]:p==='products'?[['growth','بیشترین رشد'],['price','کمترین قیمت'],['active','بیشترین تبلیغ'],['recent','جدیدترین']]:[['growth','بیشترین رشد'],['revenue','بیشترین درآمد'],['visits','بیشترین بازدید'],['active','بیشترین تبلیغ']],state.sort[p],'مرتب‌سازی')}</select>`}
function viewButtons(p=page){return`<div class="segmented" role="group" aria-label="نوع نمایش">${[[p==='products'?'list':'table','list','نمای جدول'],['grid','grid','نمای کارت']].map(([v,i,l])=>`<button type="button" data-view="${v}" data-page="${p}" class="${state.view[p]===v?'active':''}" aria-label="${l}" aria-pressed="${state.view[p]===v}">${ico(i)}</button>`).join('')}</div>`}
function filterPanel(p){const f=F(p),filterSet=p==='ads'?filterControl('platform','meta',['Meta','TikTok','YouTube'],'همهٔ رسانه‌ها',p)+filterControl('category','tag',D.categories,'همهٔ دسته‌ها',p)+filterControl('country','globe',D.countries,'همهٔ کشورها',p)+filterControl('format','ads',['تصویر','ویدیو'],'همهٔ قالب‌ها',p)+filterControl('active','clock',[[30,'حداقل ۳۰ روز'],[60,'حداقل ۶۰ روز']],'مدت فعالیت',p):p==='products'?filterControl('category','tag',D.categories,'همهٔ دسته‌ها',p)+filterControl('country','globe',D.countries,'کشور فروشگاه',p)+filterControl('price','dollar',[[50,'تا ۵۰ دلار'],[100,'تا ۱۰۰ دلار']],'بازهٔ قیمت',p)+filterControl('active','ads',[[30,'بیشتر از ۳۰ تبلیغ'],[70,'بیشتر از ۷۰ تبلیغ']],'تعداد تبلیغات',p):filterControl('category','tag',D.categories,'همهٔ دسته‌ها',p)+filterControl('country','globe',D.countries,'کشور مبدأ',p)+filterControl('revenue','dollar',[[1000,'بیش از ۱٬۰۰۰ دلار'],[3000,'بیش از ۳٬۰۰۰ دلار'],[5000,'بیش از ۵٬۰۰۰ دلار']],'درآمد روزانهٔ تخمینی',p)+filterControl('growth','chart',[[40,'بیشتر از ۴۰٪'],[70,'بیشتر از ۷۰٪'],[100,'بیشتر از ۱۰۰٪']],'رشد ۳۰ روز',p)+filterControl('active','ads',[[50,'بیش از ۵۰ تبلیغ'],[100,'بیش از ۱۰۰ تبلیغ'],[300,'بیش از ۳۰۰ تبلیغ']],'تبلیغات فعال',p);
return`<div class="filter-panel"><div class="search-line"><label class="search-field">${ico('search')}<span class="sr-only">${p==='ads'?'جست‌وجوی تبلیغات':p==='products'?'جست‌وجوی محصولات':'جست‌وجوی فروشگاه‌ها'}</span><input type="search" data-query="${p}" aria-label="${p==='ads'?'جست‌وجوی تبلیغات':p==='products'?'جست‌وجوی محصولات':'جست‌وجوی فروشگاه‌ها'}" placeholder="${p==='ads'?'جست‌وجو بر اساس متن تبلیغ، نام برند یا محصول':p==='products'?'جست‌وجو بر اساس نام محصول، فروشگاه یا دامنه':'جست‌وجو بر اساس نام فروشگاه یا دامنه'}" value="${esc(f.query||'')}" autocomplete="off"></label>${sortSelect(p)}${p==='products'?`<div class="segmented"><button data-action="one-per-shop" data-value="all" class="${!state.onePerShop?'active':''}" aria-pressed="${!state.onePerShop}">همهٔ محصولات</button><button data-action="one-per-shop" data-value="one" class="${state.onePerShop?'active':''}" aria-pressed="${state.onePerShop}">یک محصول از هر فروشگاه</button></div>`:p==='shops'?act(ico('plus')+'افزودن فروشگاه','add-shop','btn primary'):''}</div><div class="filter-row">${filterSet}</div></div>${Object.entries(f).some(([k,v])=>v&&k!=='query')?`<div class="active-filters">${Object.entries(f).filter(([k,v])=>v&&k!=='query').map(([k,v])=>`<button class="filter-chip" data-clear-filter="${k}" data-page="${p}">${esc(v)} ${ico('close')}</button>`).join('')}${act('پاک‌کردن فیلترها','clear-filters','text-link',`data-page="${p}"`)}</div>`:''}`}
function filtered(p){const f=F(p),q=(f.query||'').trim().toLowerCase();let list=(p==='ads'?D.ads:p==='products'?D.products:shops()).filter(r=>{const s=p==='shops'?r:shop(r.shop);return(!q||[r.title,r.name,r.english,r.copy,r.category,s.name,s.domain].some(x=>String(x||'').toLowerCase().includes(q)))&&(!f.category||r.category===f.category)&&(!f.country||(r.country||s.country)===f.country)&&(!f.platform||r.platform===f.platform)&&(!f.format||r.format===f.format)&&(!f.active||r.active>=+f.active)&&(!f.price||r.price<=+f.price)&&(!f.revenue||r.revenue>=+f.revenue)&&(!f.growth||r.growth>=+f.growth)&&(p!=='shops'||state.shopMode!=='tracked'||saved('shops',r.id))});const s=state.sort[p];list.sort((a,b)=>s==='recent'?(p==='ads'?a.active-b.active:String(b.published||b.created||b.id).localeCompare(String(a.published||a.created||a.id))):s==='price'?a.price-b.price:(b[s]||0)-(a[s]||0));if(p==='products'&&state.onePerShop){const seen=new Set();list=list.filter(p=>seen.has(p.shop)?false:(seen.add(p.shop),true))}return list}
function empty(title='با این فیلترها، نتیجه‌ای پیدا نشد.',desc='جست‌وجو یا فیلترها را تغییر بده و دوباره بررسی کن.',reset=true){return`<div class="empty">${ico('search')}<h3>${title}</h3><p>${desc}</p>${reset?act('پاک‌کردن فیلترها','clear-filters','btn',`data-page="${page}"`):`<a class="btn primary" href="${hashes.ads}">کشف تبلیغات ${ico('arrow')}</a>`}</div>`}
function adCard(a){const s=shop(a.shop),p=product(a.product);return`<article class="ad-card" data-card="ads"><div class="card-identity">${initials(s)}<button class="identity-name" data-open="shops" data-id="${s.id}" aria-label="فروشگاه ${esc(s.name)}"><strong>${esc(s.name)}</strong><small>${num(s.active)} تبلیغ فعال / ${compact(s.total)} کل</small></button>${platform(a)}</div><div class="ad-delivery"><span><i class="dot"></i>${num(a.active)} روز فعال</span><span>${ico('calendar')}از ${date(new Date(Date.now()-a.active*86400000).toISOString().slice(0,10)).replace(' ۱۴۰۵','')} ← امروز</span></div><div class="ad-metrics"><span>${shop(a.shop).flag}</span><span>${ico('eye')}<b class="latin">${compact(a.reach)}</b></span><span>${ico('dollar')}<b class="latin">${compact(a.spend)}</b></span><span>${ico('copy')}${num(a.variants)}</span></div><button class="ad-cover" data-open="ads" data-id="${a.id}" aria-label="پیش‌نمایش تبلیغ ${esc(a.title)}">${media(a.media,a.title)}${a.format==='ویدیو'?`<span class="play"><span>${ico('play')}</span></span>`:''}<span class="format-label">${a.format==='ویدیو'?'فریم تبلیغ ویدیویی':'تبلیغ تصویری'}</span></button><div class="ad-landing"><button class="landing-link" data-open="shops" data-id="${s.id}"><small>صفحهٔ مقصد</small><span class="latin">${esc(s.domain)}</span>${ico('arrowUp')}</button><span class="landing-thumb">${media(p.media,p.name)}</span></div><footer class="ad-footer"><button class="btn" data-open="ads" data-id="${a.id}">تحلیل تبلیغ</button>${saveButton('ads',a.id,'ذخیرهٔ تبلیغ '+a.title)}<button class="icon-btn" data-action="ad-menu" data-id="${a.id}" aria-label="گزینه‌های تبلیغ ${esc(a.title)}">${ico('more')}</button></footer></article>`}
function adsTable(items){return`<div class="table-wrap"><table class="report-table"><caption class="sr-only">جدول تبلیغات نمونه</caption><thead><tr><th>تبلیغ</th><th>رسانه</th><th>بازدید</th><th>روز فعالیت</th><th>ROAS</th><th>CTR</th><th>ذخیره</th></tr></thead><tbody>${items.map(a=>`<tr><td><button class="report-title-cell" data-open="ads" data-id="${a.id}"><span class="report-mini-media">${media(a.media)}</span><span><strong>${a.title}</strong><small class="latin">${shop(a.shop).name}</small></span></button></td><td>${platform(a)}</td><td class="latin">${compact(a.reach)}</td><td>${num(a.active)}</td><td><span class="pill good latin">${a.roas}</span></td><td class="latin">${a.ctr}%</td><td>${saveButton('ads',a.id,'ذخیرهٔ تبلیغ '+a.title)}</td></tr>`).join('')}</tbody></table></div>`}
function productRow(p){const s=shop(p.shop),related=D.ads.filter(a=>a.product===p.id),photos=related.length?related:D.ads.filter(a=>a.shop===p.shop).slice(0,3);return`<article class="product-row" data-card="products"><div class="product-main"><button class="product-picture" data-open="products" data-id="${p.id}" aria-label="جزئیات محصول ${p.name}">${media(p.media,p.name)}</button><div class="product-copy"><h3>${p.name}</h3><span class="latin">${p.english}</span><span class="published">${ico('calendar')}معرفی‌شده در ${date(p.published)}</span><strong class="product-price">${money(p.price)}</strong><footer><button class="shop-domain" data-open="shops" data-id="${s.id}">${s.domain}</button>${saveButton('products',p.id,'ذخیرهٔ محصول '+p.name)}</footer></div></div><div class="product-shop"><h4>اطلاعات فروشگاه</h4><div class="shop-name-cell">${initials(s)}<strong>${s.name}</strong></div><span class="country-cell"><span class="flag">${s.flag}</span>${s.country}</span><span class="pill good">${ico('chart')}${num(p.growth)}٪ رشد نمونه</span><button class="text-link" data-open="shops" data-id="${s.id}">بررسی فروشگاه ←</button></div><div class="product-ads"><header><h4>تبلیغات مرتبط</h4><span class="active-number">${num(p.active)} فعال</span></header><div class="product-ad-thumbs">${photos.slice(0,3).map(a=>thumb(a.media,'ads',a.id,a.format==='ویدیو')).join('')}</div><button class="text-link" data-open="products" data-id="${p.id}">تحلیل محصول ${ico('arrow')}</button></div></article>`}
function shopActions(s){return`<div class="table-actions"><button class="icon-btn" data-action="alert" data-id="${s.id}" aria-pressed="${state.alerts.includes(s.id)}" aria-label="اعلان فروشگاه ${esc(s.name)}">${ico('bell')}</button><button class="icon-btn" data-open="shops" data-id="${s.id}" aria-label="تحلیل فروشگاه ${esc(s.name)}">${ico('eye')}</button>${saveButton('shops',s.id,'پیگیری فروشگاه '+s.name)}</div>`}
function shopsTable(items){return`<div class="table-wrap"><table class="shops-table"><caption class="sr-only">فروشگاه‌ها، رشد، درآمد تخمینی و تبلیغات مرتبط؛ دادهٔ نمونه</caption><thead><tr><th>فروشگاه</th><th>درآمد روزانهٔ تخمینی</th><th>بازدید ماهانه</th><th>تبلیغات</th><th>محصولات</th><th>ترافیک بر اساس کشور</th><th>عملیات</th></tr></thead><tbody>${items.map(s=>`<tr data-card="shops"><td><button class="shop-name-cell" data-open="shops" data-id="${s.id}">${initials(s)}<strong>${esc(s.name)}</strong></button><button class="shop-domain" data-open="shops" data-id="${s.id}">${esc(s.domain)}</button><span class="created">${s.pending?'فروشگاه افزوده‌شده · بدون داده':'تاریخ ایجاد: '+date(s.created)}</span></td><td><strong class="value small-value">${money(s.revenue)}</strong><span class="metric-label">${s.pending?'در انتظار داده':'USD · نمونهٔ تخمینی'}</span></td><td><strong class="value">${compact(s.visits)}</strong><div class="growth-row">${s.growth==null?'—':`<span class="pill good">↑ ${num(s.growth)}٪</span>`}<span>۳۰ روز</span></div>${spark(s.trend)}</td><td><strong class="active-number">${num(s.active)} فعال</strong><span class="muted"> / ${compact(s.total)} کل</span><div class="mini-stack">${D.ads.filter(a=>a.shop===s.id).slice(0,3).map(a=>thumb(a.media,'ads',a.id,a.format==='ویدیو')).join('')||'<span class="muted">هنوز تبلیغی ندارد</span>'}</div></td><td><strong class="value small-value">${num(s.products)}</strong><div class="mini-stack">${D.products.filter(p=>p.shop===s.id).slice(0,3).map(p=>thumb(p.media,'products',p.id)).join('')}</div></td><td><div class="country-cell"><span class="flag">${s.flag}</span><span>${s.country}<small class="metric-label">${s.pending?'—':'۷۲٪ سهم نمونه'}</small></span></div></td><td>${shopActions(s)}</td></tr>`).join('')}</tbody></table></div>`}
function shopCard(s){return`<article class="shop-card" data-card="shops"><button class="shop-name-cell" data-open="shops" data-id="${s.id}">${initials(s)}<span><strong>${esc(s.name)}</strong><small class="shop-domain">${esc(s.domain)}</small></span></button><span class="country-cell"><span class="flag">${s.flag}</span>${s.country}<span class="pill good">${s.growth==null?'بدون داده':num(s.growth)+'٪ رشد'}</span></span>${spark(s.trend,true)}<div class="shop-stats"><div><span class="value">${money(s.revenue)}</span><small class="metric-label">درآمد روزانهٔ تخمینی</small></div><div><span class="value">${compact(s.visits)}</span><small class="metric-label">بازدید ماهانه</small></div></div><footer><button class="btn" data-open="shops" data-id="${s.id}">تحلیل فروشگاه</button>${saveButton('shops',s.id,'پیگیری فروشگاه '+s.name)}</footer></article>`}
function tabs(type,selected){return`<div class="tabs" role="group" aria-label="نوع نتایج">${[['ads','تبلیغات'],['products','محصولات'],['shops','فروشگاه‌ها']].map(([v,l])=>`<button class="tab ${selected===v?'active':''}" data-tab="${type}" data-value="${v}" aria-pressed="${selected===v}">${l}</button>`).join('')}</div>`}
function renderItems(p,items,view=state.view[p]){if(!items.length)return empty();if(p==='ads')return view==='table'?adsTable(items):`<div class="ad-grid">${items.map(adCard).join('')}</div>`;if(p==='products')return`<div class="${view==='grid'?'product-row-grid':'product-list'}">${items.map(productRow).join('')}</div>`;return view==='grid'?`<div class="shop-grid">${items.map(shopCard).join('')}</div>`:shopsTable(items)}
function paginate(items,p){const size=p==='ads'?8:p==='products'?6:8,max=Math.max(1,Math.ceil(items.length/size));state.pagination[p]=Math.min(max,state.pagination[p]||1);return{items:items.slice((state.pagination[p]-1)*size,state.pagination[p]*size),footer:`<div class="pagination"><span>نمایش ${num(Math.min(items.length,(state.pagination[p]-1)*size+1))} تا ${num(Math.min(items.length,state.pagination[p]*size))} از ${num(items.length)} نتیجه</span><div><button class="icon-btn" data-pagination="-1" data-page="${p}" ${state.pagination[p]===1?'disabled':''} aria-label="صفحهٔ قبل">${ico('left')}</button><button class="btn small" disabled>${fa(state.pagination[p])}</button><button class="icon-btn" data-pagination="1" data-page="${p}" ${state.pagination[p]===max?'disabled':''} aria-label="صفحهٔ بعد">${ico('left').replace('class="icon','style="transform:rotate(180deg)" class="icon')}</button></div></div>`}}
function catalogPage(p){const isShops=p==='shops',isProducts=p==='products',list=filtered(p),pg=paginate(list,p);return head(isShops?'فروشگاه‌های رو به رشد':isProducts?'محصول بعدی را زودتر پیدا کن.':'تبلیغ خوب، یک اتفاق نیست.',isShops?'رشد، ترافیک و تبلیغات هر فروشگاه را در یک نما مقایسه کن.':isProducts?'محصول، فروشگاه و تبلیغات مرتبط؛ کنار هم برای یک بررسی دقیق‌تر.':'از پیام و قالب تا عملکرد؛ دلیل دیده‌شدن هر تبلیغ را بررسی کن.',isShops?'ANALYZE / SHOPS':isProducts?'ANALYZE / PRODUCTS':'ANALYZE / ADS',isShops?'':act(ico('download')+'خروجی CSV','export','btn'))+filterPanel(p)+`<div class="results-bar">${p==='ads'?`<div class="tabs" aria-label="رسانهٔ تبلیغات">${['','Meta','TikTok','YouTube'].map(v=>`<button class="tab ${(F(p).platform||'')===v?'active':''}" data-platform="${v}" aria-pressed="${(F(p).platform||'')===v}">${v||'همهٔ تبلیغات'}</button>`).join('')}</div>`:p==='shops'?`<div class="tabs"><button class="tab ${state.shopMode==='all'?'active':''}" data-action="shop-mode" data-value="all">همهٔ فروشگاه‌ها</button><button class="tab ${state.shopMode==='tracked'?'active':''}" data-action="shop-mode" data-value="tracked">پیگیری‌شده‌ها ${fa(state.saved.shops.length)}</button></div>`:`<span class="muted">${num(list.length)} محصول مطابق انتخاب شما</span>`}<span class="muted">${num(list.length)} نتیجه · دادهٔ نمونه</span>${viewButtons(p)}</div>`+renderItems(p,pg.items)+pg.footer}
function lineChart(values,labels=null){const width=600,height=240,l=42,r=18,t=18,b=34,w=width-l-r,h=height-t-b,max=Math.ceil(Math.max(...values)*1.12/10)*10;const pts=values.map((v,i)=>[l+i/(values.length-1)*w,t+h-v/max*h]),poly=pts.map(p=>p.join(',')).join(' '),ticks=[0,.25,.5,.75,1];return`<svg class="chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="روند نمونه در ${fa(state.period)} روز؛ از ${num(values[0])} تا ${num(values.at(-1))}"><title>روند نمونهٔ بازدید و توجه به بازار</title>${ticks.map(v=>`<line class="chart-grid-line" x1="${l}" y1="${t+h-v*h}" x2="${width-r}" y2="${t+h-v*h}"/><text x="${l-10}" y="${t+h-v*h+3}" text-anchor="end" class="chart-label">${fa(Math.round(v*max))}</text>`).join('')}<polygon class="chart-area" points="${l},${t+h} ${poly} ${width-r},${t+h}"/><polyline points="${pts.map(([x,y],i)=>[x,t+h-(values[i]*.74+9)/max*h].map(v=>v.toFixed(1)).join(',')).join(' ')}" fill="none" stroke="var(--muted)" stroke-dasharray="4 7" stroke-width="1.4"/><polyline class="chart-line" points="${poly}"/>${pts.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="3.2" fill="var(--chart)"><title>نقطهٔ ${num(i+1)}: ${num(values[i])}</title></circle>`).join('')}${[0,2,4,6,8,10,11].filter(i=>i<values.length).map(i=>`<text x="${pts[i][0]}" y="${height-9}" class="chart-label" text-anchor="middle">${i===values.length-1?'امروز':fa(Math.round((i+1)/values.length*state.period))+' روز'}</text>`).join('')}</svg><div class="chart-note"><i class="legend-mark"></i>شاخص نسبی نمونه <span style="margin-right:auto">خط‌چین: مقایسهٔ فرضی</span></div>`}
function demandValues(){const base=[24,28,25,38,35,46,52,49,61,68,73,84];return state.period===7?base.map((v,i)=>Math.round(v*.84+(i%3)*6)):state.period===90?base.map((v,i)=>Math.round(v*.93+(i%4)*4)):base}
function donut(){const segments=[['Meta',62,'var(--chart)'],['TikTok',26,'#ff9ba1'],['YouTube',12,'#ddd7e6']];let offset=0;return`<div class="donut-layout"><div class="donut"><svg viewBox="0 0 140 140" role="img" aria-label="سهم رسانه‌ها در نمونه: متا ۶۲ درصد، تیک‌تاک ۲۶ درصد، یوتیوب ۱۲ درصد">${segments.map(([n,v,c])=>{const part=`<circle cx="70" cy="70" r="55" pathLength="100" fill="none" stroke="${c}" stroke-width="15" stroke-dasharray="${v-1.5} ${100-v+1.5}" stroke-dashoffset="${-offset}"/>`;offset+=v;return part}).join('')}</svg><div class="donut-center"><strong>3</strong><small>رسانه</small></div></div><div class="legend">${segments.map(([n,v,c])=>`<div><i style="background:${c}"></i><span class="latin">${n}</span><strong>${v}%</strong></div>`).join('')}</div></div>`}
function reportPage(){const focus=state.reportType||'ads',stats=[['ads','تبلیغات بررسی‌شده',num(D.ads.length),'۱۰ نمونه برای شروع'],['shop','فروشگاه‌های کشف‌شده',num(shops().length),'۶ فروشگاه با دادهٔ نمونه'],['product','محصولات منتخب',num(D.products.length),'۴ دستهٔ قابل بررسی'],['target','میانگین ROAS نمونه',(D.ads.reduce((a,b)=>a+b.roas,0)/D.ads.length).toFixed(2),'دادهٔ سناریوی دمو']];const top=[...D.ads].sort((a,b)=>b.roas-a.roas).slice(0,5);return head('یک نمای روشن از حرکت بازار.','روندها، تبلیغات و فروشگاه‌ها را کنار هم ببین و مقایسه کن.','ANALYZE / REPORTS',act(ico('download')+'خروجی گزارش','export','btn')+act(ico('plus')+'گزارش جدید','new-report','btn primary'))+`<div class="kpi-grid">${stats.map(([i,l,v,sub])=>`<article class="kpi"><span>${l}</span>${ico(i)}<strong class="value">${v}</strong><span class="pill good">${sub}</span></article>`).join('')}</div><div class="charts-grid"><section class="chart-panel"><header class="chart-head"><div><h3>نبض توجه در بازار</h3><p>شاخص نسبی · مقایسهٔ داده‌های نمونه</p></div><select class="sort-select" data-control="period" aria-label="بازهٔ نمودار">${[7,30,90].map(n=>`<option value="${n}" ${state.period===n?'selected':''}>${fa(n)} روز گذشته</option>`).join('')}</select></header>${lineChart(demandValues())}</section><section class="chart-panel"><header class="chart-head"><div><h3>سهم رسانه‌ها</h3><p>ترکیب فرضی بازدید تبلیغات</p></div><span class="pill red">نمونه</span></header>${donut()}</section></div><div class="insight-strip">${ico('spark')}<div><h3>نمایش کاربرد، یک زاویهٔ مناسب برای بررسی است.</h3><p>در سناریوی نمونه، تبلیغ‌های محصول‌محور عملکرد بالاتری دارند؛ جزئیات را مقایسه کن.</p></div><a class="btn" href="${hashes.ads}">بررسی تبلیغات ${ico('arrow')}</a></div><div class="charts-grid"><section class="chart-panel"><header class="chart-head"><div><h3>${focus==='shops'?'فروشگاه‌های منتخب گزارش':focus==='products'?'محصولات منتخب گزارش':'تبلیغ‌های برتر این نمونه'}</h3><p>${focus==='ads'?'مرتب‌شده بر اساس ROAS نمایشی':'مقایسه بر اساس رشد نمونه'}</p></div><a class="text-link" href="${hashes[focus]}">همهٔ ${focus==='shops'?'فروشگاه‌ها':focus==='products'?'محصولات':'تبلیغات'} ←</a></header>${focus==='shops'?shopsTable([...D.shops].sort((a,b)=>b.growth-a.growth).slice(0,4)):focus==='products'?`<div class="saved-report-list">${[...D.products].sort((a,b)=>b.growth-a.growth).slice(0,4).map(p=>`<button class="saved-report" data-open="products" data-id="${p.id}"><span>${p.name}</span><span class="pill good">${num(p.growth)}٪ رشد</span></button>`).join('')}</div>`:adsTable(top)}</section><section class="chart-panel"><header class="chart-head"><div><h3>رشد فروشگاه‌ها</h3><p>درصد تغییر نمونه در ۳۰ روز</p></div></header><div class="bar-chart">${[...D.shops].sort((a,b)=>b.growth-a.growth).map(s=>`<div class="bar-row"><button class="latin" data-open="shops" data-id="${s.id}" style="font-size:9px;text-align:right">${s.name.split(' ')[0]}</button><span class="bar-track"><i style="width:${s.growth/120*100}%"></i></span><strong class="latin">${s.growth}%</strong></div>`).join('')}</div><span class="detail-note">نمودار برای بررسی طراحی رابط است.</span></section></div>${state.reports.length?`<section class="section">${sectionHead('گزارش‌های ذخیره‌شده','تنظیمات گزارش در همین مرورگر ذخیره شده است.')}<div class="saved-report-list">${state.reports.map(r=>`<div class="saved-report"><span>${esc(r.name)} <small class="muted">· ${fa(r.period)} روز</small></span>${act('بازکردن گزارش','open-report','btn small',`data-id="${r.id}"`)}</div>`).join('')}</div></section>`:''}`}
function home(){const mediaKeys=['wellness','home','care','razor','fashion','bottle','wardrobe','atelier','scrubber','bottle'],offset=state.day===4?0:state.day+1,p=state.topTab,items=(p==='ads'?D.ads:p==='products'?D.products:D.shops),ordered=[...items.slice(offset%items.length),...items.slice(0,offset%items.length)].slice(0,p==='ads'?4:3);return`<section class="home-hero"><img class="hero-mark" src="assets/mark.svg" alt="نشان نما"><span class="eyebrow" style="font-size:8px;margin-bottom:8px">YOUR MARKET, IN FOCUS</span><h1>آریا، فرصت بعدی را <em>روشن‌تر</em> ببین.</h1><p class="hero-sub">دستیار تحلیل بازار تو؛ از کشف تبلیغات و محصولات برنده<br>تا شناخت فروشگاه‌های رو به رشد، همه در یک فضای کاری.</p><form class="hero-ask" data-form="ask"><label class="sr-only" for="heroQuestion">پرسش دربارهٔ بازار</label><input id="heroQuestion" name="question" required placeholder="دربارهٔ چه بازار، محصول یا رقیبی کنجکاوی؟" autocomplete="off"><button class="btn black" type="submit">از نما بپرس ${ico('arrow')}</button></form><div class="hero-prompts">${[['تبلیغات رو به رشد را از کجا پیدا کنم؟','ads'],['کدام فروشگاه‌ها سریع‌تر رشد می‌کنند؟','shops'],['محصولات محبوب هر دسته را مقایسه کن.','products']].map(([text,type])=>`<button class="prompt-card" data-action="prompt" data-value="${type}">${ico(type==='ads'?'ads':type==='shops'?'chart':'product')}<span>${text}</span></button>`).join('')}</div></section><div class="setup-grid">${[['target','بازارت را مشخص کن','دسته، کشور و رسانهٔ مناسب را انتخاب کن.','شروع کاوش','ads'],['shop','رقیبت را زیر نظر بگیر','فروشگاه‌ها و تبلیغ‌های مرتبط را یک‌جا ببین.','افزودن فروشگاه','add-shop'],['chart','اولین گزارشت را بساز','یافته‌ها را کنار هم قرار بده و مقایسه کن.','ساخت گزارش','new-report']].map(([i,t,d,l,a])=>`<article class="setup-card"><span class="setup-icon">${ico(i)}</span><div><h3>${t}</h3><p>${d}</p><button data-action="${a}">${l} ${ico('arrow')}</button></div></article>`).join('')}</div><section class="section"><div class="promo-row"><article class="promo"><div><span class="eyebrow" style="font-size:8px;color:#ff9298">DISCOVER THE SIGNAL</span><h3>تبلیغ را ببین.<br>دلیل اثرگذاری‌اش را کشف کن.</h3><p>از پیام و قالب تا فعالیت و عملکرد؛ سرنخ‌ها را کنار هم بچین.</p><a href="${hashes.ads}">کاوش تبلیغات ${ico('arrow')}</a></div><div class="promo-visual" aria-hidden="true">${media('fashion')}${media('wellness')}</div></article><article class="promo red-promo"><div><span class="eyebrow" style="font-size:8px;color:#ffd3d7">WATCH WHAT'S GROWING</span><h3>قبل از همه،<br>رشد را پیدا کن.</h3><p>فروشگاه‌ها، محصولات و تبلیغات مرتبط با بازار تو.</p><a href="${hashes.shops}">کشف فروشگاه‌ها ${ico('arrow')}</a></div><span class="promo-index">↗</span><svg class="promo-chart" viewBox="0 0 230 130" aria-hidden="true"><path d="M0 120 20 117 45 112 70 100 100 103 130 77 155 80 180 45 205 31 230 3V130H0Z" fill="#fff"/></svg></article></div></section><section class="section">${sectionHead('برترین‌های امروز','مرور نمونهٔ تبلیغات، محصولات و فروشگاه‌های رو به رشد.')}<div class="days-row" aria-label="مرور انتخاب‌های نمونه">${mediaKeys.map((m,i)=>{const d=new Date();d.setDate(d.getDate()-(4-i));return`<button class="day-card ${state.day===i?'active':''}" data-day="${i}" aria-pressed="${state.day===i}" aria-label="انتخاب نمونهٔ ${fa(i+1)}">${media(m)}<span class="day-label">${i===4?'امروز':new Intl.DateTimeFormat('fa-IR',{weekday:'short',timeZone:'Europe/Bucharest'}).format(d)}<small>${i===4?'منتخب دمو':new Intl.DateTimeFormat('fa-IR',{day:'numeric',month:'short',timeZone:'Europe/Bucharest'}).format(d)}</small></span></button>`}).join('')}</div><div class="results-bar" style="margin:18px 0 21px">${tabs('top',p)}<a class="text-link" href="${hashes[p]}">دیدن همهٔ ${p==='ads'?'تبلیغات':p==='products'?'محصولات':'فروشگاه‌ها'} ${ico('arrow')}</a></div>${renderItems(p,ordered,p==='ads'?'grid':p==='products'?'grid':'grid')}</section><section class="home-insights"><article class="chart-panel"><header class="chart-head"><div><h3>یک نگاه به نبض بازار</h3><p>روند فرضی توجه · ${fa(state.period)} روز</p></div><a class="text-link" href="${hashes.reports}">گزارش کامل ←</a></header>${lineChart(demandValues())}</article><article class="chart-panel"><header class="chart-head"><div><h3>فروشگاه‌های در حال رشد</h3><p>سه نمونه برای شروع بررسی</p></div></header><div class="bar-chart">${[...D.shops].sort((a,b)=>b.growth-a.growth).slice(0,3).map(s=>`<div class="bar-row"><button class="latin" data-open="shops" data-id="${s.id}" style="font-size:9px;text-align:right">${s.name.split(' ')[0]}</button><span class="bar-track"><i style="width:${s.growth/120*100}%"></i></span><strong class="latin">${s.growth}%</strong></div>`).join('')}</div><a class="text-link" href="${hashes.shops}">مقایسهٔ همهٔ فروشگاه‌ها ←</a></article></section>`}
function savedPage(){const p=state.savedTab,list=(p==='ads'?D.ads:p==='products'?D.products:shops()).filter(r=>saved(p,r.id));return head('یافته‌های خوب را کنار هم نگه دار.','تبلیغات، محصولات و فروشگاه‌هایی که ذخیره کرده‌ای؛ آمادهٔ مقایسه و بررسی.','ANALYZE / COLLECTIONS')+`<div class="results-bar">${tabs('saved',p)}<span class="muted">${num(list.length)} مورد ذخیره‌شده</span></div>`+(list.length?renderItems(p,list,p==='shops'?'table':p==='products'?'list':'grid'):empty('هنوز موردی اینجا ذخیره نشده است.','در کارت تبلیغ، محصول یا ردیف فروشگاه، نشان ذخیره را بزن.',false))}
function resolveRoute(){let h;try{h=decodeURIComponent(location.hash).replace(/^#\/?/,'').replace(/\/+$/,'')}catch{h=''}if(h===''||h==='portal')return{page:'portal',legacy:false};if(h==='start'||h.startsWith('start/')){const steps=['idea','customer','goal'],step=Math.max(0,steps.indexOf(h.split('/')[1]));return{page:'start',step,legacy:false}}const alias={home:'home',analyze:'reports',discover:'ads',report:'reports','report-table':'reports',formats:'reports',competitors:'shops',audience:'reports',library:'saved','dark-analyze':'reports',ads:'ads',shops:'shops',products:'products',reports:'reports',saved:'saved','workspace':'home','workspace/home':'home','workspace/overview':'reports','workspace/ads':'ads','workspace/products':'products','workspace/shops':'shops','workspace/reports':'reports','workspace/reports/table':'reports','workspace/market':'ads','workspace/competitors':'shops','workspace/audience':'reports','workspace/campaigns':'ads','workspace/formats':'reports','workspace/saved':'saved','workspace/library':'saved'};const legacy=/release|studio|stories|calendar|approvals/.test(h);return{page:alias[h]||'home',legacy}}
function render(){const entry=page==='portal'||page==='start',theme=entry?window.NAMA_ENTRY.theme():state.theme;document.body.dataset.theme=theme;document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#09061a':'#f8f9fb';document.title=page==='portal'?'NAMA — از ایده تا یک مسیر روشن':page==='start'?'NAMA · شروع پروژه':'NAMA Analyze · '+headerTitle();app.innerHTML=page==='portal'?window.NAMA_ENTRY.portal():page==='start'?window.NAMA_ENTRY.discovery(resolveRoute().step):shell(page==='home'?home():page==='reports'?reportPage():page==='saved'?savedPage():catalogPage(page));if(!entry)syncSaves()}
function navigate(next){if(!hashes[next])next='home';page=next;mobileMenu=false;history.pushState(null,'',hashes[page]);menu.hidden=true;render();window.scrollTo(0,0)}
function readRoute(){const route=resolveRoute();if(route.page==='start'){const safe=window.NAMA_ENTRY.guard(route.step);if(safe!==route.step){history.replaceState(null,'','#/start/'+['idea','customer','goal'][safe]);route.step=safe}}page=route.page;mobileMenu=false;if(dialog.open)dialog.close();menu.hidden=true;render();if(route.legacy){history.replaceState(null,'',hashes.home);toast('این نسخه فقط به Analyze اختصاص دارد.')}window.scrollTo(0,0)}
function openDialog(title,subtitle,content,wide=false){dialog.classList.toggle('wide',wide);dialog.innerHTML=`<header class="dialog-header"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button type="button" class="icon-btn" data-action="close-dialog" aria-label="بستن">${ico('close')}</button></header><div class="dialog-content">${content}</div>`;menu.hidden=true;if(!dialog.open)dialog.showModal();syncSaves()}
function metric(label,value){return`<div><small>${label}</small><strong>${value}</strong></div>`}
function adDetail(id){const a=ad(id),s=shop(a.shop),p=product(a.product);openDialog('تحلیل تبلیغ','نمایش پیام، عملکرد و فروشگاه مرتبط · دادهٔ نمونه',`<div class="detail-layout"><div><div class="detail-media">${media(a.media,a.title)}</div><p class="detail-note">${a.format==='ویدیو'?'تصویر، فریم مرجع تبلیغ است؛ ویدیوی اصلی این نمونه در دسترس نیست.':'تصویر مرجع برای نمایش طراحی کارت و تحلیل.'}</p></div><div><div class="detail-meta">${platform(a)}<span class="pill good">${num(a.active)} روز فعال</span><span class="pill">${s.flag} ${s.country}</span></div><h2 style="font-size:21px">${a.title}</h2><button class="shop-domain" data-open="shops" data-id="${s.id}" style="margin-top:9px">${s.name} · ${s.domain}</button><div class="detail-kpis">${metric('بازدید نمونه',compact(a.reach))}${metric('ROAS',a.roas)}${metric('CTR',a.ctr+'%')}</div><div class="detail-copy">${a.copy}</div><div class="tabs">${a.tags.map(t=>`<span class="pill red">${t}</span>`).join('')}</div><section class="detail-section"><h3>روند توجه به تبلیغ</h3>${spark(a.trend,true)}<p class="detail-note">شاخص نسبی، از ${num(a.trend[0])} تا ${num(a.trend.at(-1))} · نمونه</p></section><div class="dialog-actions"><button class="btn" data-open="products" data-id="${p.id}">${ico('product')}محصول مرتبط</button>${act(ico('copy')+'کپی متن','copy-ad','btn',`data-id="${a.id}"`)}${saveButton('ads',a.id,'ذخیرهٔ تبلیغ '+a.title)}</div></div></div>`,true)}
function productDetail(id){const p=product(id),s=shop(p.shop),related=D.ads.filter(a=>a.product===id);openDialog('تحلیل محصول','محصول، فروشگاه و تبلیغات مرتبط در یک نما',`<div class="detail-layout"><div class="detail-media">${media(p.media,p.name)}</div><div><span class="eyebrow">PRODUCT INTELLIGENCE</span><h2>${p.name}</h2><span class="muted latin" style="font-size:10px">${p.english}</span><p class="product-price" style="margin-top:13px">${money(p.price)}</p><p class="detail-copy">${p.description}</p><div class="detail-kpis">${metric('تبلیغات فعال',num(p.active))}${metric('رشد نمونه',p.growth+'%')}${metric('رسانه‌های مرتبط',num(new Set(related.map(a=>a.platform)).size))}</div><button class="internal-link" data-open="shops" data-id="${s.id}">${ico('shop')}${s.name} ←</button><section class="detail-section"><h3>تبلیغات مرتبط</h3><div class="mini-stack">${related.map(a=>thumb(a.media,'ads',a.id,a.format==='ویدیو')).join('')||'<small class="muted">در این نمونه تبلیغی مرتبط نشده است.</small>'}</div></section><div class="dialog-actions">${saveButton('products',p.id,'ذخیرهٔ محصول '+p.name)}<button class="btn primary" data-open="shops" data-id="${s.id}">بررسی فروشگاه ${ico('arrow')}</button></div></div></div>`,true)}
function shopDetail(id){const s=shop(id),related=D.ads.filter(a=>a.shop===id),products=D.products.filter(p=>p.shop===id);openDialog(s.name,'جزئیات فروشگاه و سیگنال‌های رشد · دادهٔ نمونه',`<div style="display:flex;align-items:center;gap:14px">${initials(s)}<span class="latin">${esc(s.domain)}</span><span class="pill">${s.flag} ${s.country}</span><span style="margin-right:auto">${saveButton('shops',s.id,'پیگیری فروشگاه '+s.name)}</span></div><div class="detail-kpis">${metric('درآمد روزانهٔ تخمینی',money(s.revenue))}${metric('بازدید ماهانه',compact(s.visits))}${metric('تبلیغات فعال',num(s.active))}</div>${s.pending?`<div class="detail-copy">این فروشگاه به فهرست محلی اضافه شده است. داده یا تحلیل زنده برای آن دریافت نشده است.</div>`:`<section class="chart-panel" style="margin:19px 0"><header class="chart-head"><div><h3>روند رشد نمونه</h3><p>۳۰ روز گذشته · ${num(s.growth)}٪ تغییر فرضی</p></div><span class="pill good">↑ ${s.growth}%</span></header>${spark(s.trend,true)}</section>`}<div class="charts-grid"><section class="detail-section"><h3>تبلیغات فروشگاه</h3><div class="mini-stack">${related.map(a=>thumb(a.media,'ads',a.id,a.format==='ویدیو')).join('')||'<span class="muted">بدون تبلیغ در نمونه</span>'}</div></section><section class="detail-section"><h3>محصولات مرتبط</h3><div class="mini-stack">${products.map(p=>thumb(p.media,'products',p.id)).join('')||'<span class="muted">بدون محصول در نمونه</span>'}</div></section></div><div class="dialog-actions">${act(ico('bell')+(state.alerts.includes(id)?'اعلان روشن است':'پیگیری تغییرات'),'alert','btn',`data-id="${s.id}"`)}<button class="btn primary" data-action="shop-ads" data-id="${s.id}">بررسی تبلیغات این فروشگاه ${ico('arrow')}</button></div><p class="dialog-hint">وضعیت پیگیری در این مرورگر ذخیره می‌شود؛ اعلان خودکار یا بررسی زنده فعال نیست.</p>`,true)}
function openEntity(type,id){if(type==='ads')adDetail(id);else if(type==='products')productDetail(id);else shopDetail(id)}
function syncSaves(){document.querySelectorAll('[data-save]').forEach(b=>b.setAttribute('aria-pressed',saved(b.dataset.save,b.dataset.id)));document.querySelectorAll('[data-action="alert"]').forEach(b=>b.setAttribute('aria-pressed',state.alerts.includes(b.dataset.id)))}
function toggleSave(type,id){const i=state.saved[type].indexOf(id);if(i<0)state.saved[type].push(id);else state.saved[type].splice(i,1);persist();render();toast(i<0?type==='shops'?'فروشگاه به پیگیری‌شده‌ها اضافه شد.':'در ذخیره‌شده‌ها اضافه شد.':'از فهرست ذخیره‌شده‌ها برداشته شد.')}
function workspaceDialog(){const brief=state.projectBrief;openDialog('فضای کاری تو','نام و اطلاعات اولیهٔ این پروژه در مرورگر ذخیره می‌شوند.',`${brief?`<section class="project-brief-summary"><h3>پروفایل اولیهٔ پروژه</h3><p><small>ایده</small><br>${esc(brief.idea)}</p><p><small>مشتری</small><br>${esc(brief.customer||brief.audienceLabel||'مشخص نشده')}</p><p><small>هدف</small><br>${esc(brief.goalLabel)}${brief.goalNote?' · '+esc(brief.goalNote):''}</p>${brief.market?`<p><small>بازار اولیه</small><br>${esc(brief.market)}</p>`:''}${brief.budget?`<p><small>بودجهٔ آزمایش</small><br>${esc(brief.budget)}</p>`:''}${act('ویرایش پاسخ‌های پروژه','edit-brief','btn small')}</section>`:''}<form data-form="workspace"><div class="form-field"><label for="workspaceName">نام فضای کاری</label><input id="workspaceName" name="name" required maxlength="45" value="${esc(state.workspace)}"></div><div class="dialog-actions">${act('انصراف','close-dialog','btn')}<button class="btn primary" type="submit">ذخیرهٔ تغییرات</button></div></form>`)}
function addShop(){openDialog('افزودن فروشگاه','فروشگاه را برای بررسی و پیگیری در دمو نگه دار.',`<form data-form="add-shop"><div class="form-field"><label for="shopName">نام فروشگاه *</label><input id="shopName" name="name" required placeholder="مثلاً استودیو پوشاک" maxlength="70"></div><div class="form-field"><label for="shopDomain">دامنهٔ فروشگاه *</label><input id="shopDomain" name="domain" required dir="ltr" placeholder="yourshop.example" autocomplete="off"></div><div class="form-grid"><div class="form-field"><label for="shopCategory">دسته</label><select id="shopCategory" name="category">${D.categories.map(c=>`<option>${c}</option>`).join('')}</select></div><div class="form-field"><label for="shopCountry">کشور</label><select id="shopCountry" name="country">${D.countries.map(c=>`<option>${c}</option>`).join('')}</select></div></div><p class="dialog-hint">در این نسخه فروشگاه به فهرست محلی اضافه می‌شود؛ داده یا درآمدی برای آن ساخته نمی‌شود.</p><p class="dialog-error" id="shopError" role="alert"></p><div class="dialog-actions">${act('انصراف','close-dialog','btn')}<button class="btn primary" type="submit">افزودن فروشگاه ${ico('plus')}</button></div></form>`)}
function newReport(){openDialog('یک گزارش روشن بساز.','تنظیمات گزارش در فضای همین مرورگر ذخیره می‌شود.',`<form data-form="new-report"><div class="form-field"><label for="reportName">نام گزارش *</label><input id="reportName" name="name" required maxlength="70" placeholder="مثلاً فرصت‌های بازار پوشاک"></div><div class="form-grid"><div class="form-field"><label for="reportPeriod">بازهٔ نمونه</label><select id="reportPeriod" name="period"><option value="7">۷ روز</option><option value="30" selected>۳۰ روز</option><option value="90">۹۰ روز</option></select></div><div class="form-field"><label for="reportType">تمرکز گزارش</label><select id="reportType" name="type"><option value="ads">عملکرد تبلیغات</option><option value="shops">فروشگاه‌ها و رشد</option><option value="products">محصولات و تبلیغات</option></select></div></div><div class="dialog-actions">${act('انصراف','close-dialog','btn')}<button class="btn primary" type="submit">ساخت گزارش نمونه ${ico('arrow')}</button></div></form>`)}
function askQuestion(q,type){const guessed=type||(/فروشگاه|رقیب/.test(q)?'shops':/محصول/.test(q)?'products':'ads'),list=guessed==='shops'?[...D.shops].sort((a,b)=>b.growth-a.growth).slice(0,3):guessed==='products'?[...D.products].sort((a,b)=>b.growth-a.growth).slice(0,3):[...D.ads].sort((a,b)=>b.roas-a.roas).slice(0,3);openDialog('یک نقطهٔ شروع برای بررسی',q||'پیشنهادهای نما برای مرور این نمونه',`<div class="detail-copy">${guessed==='shops'?'در داده‌های نمونه، این سه فروشگاه رشد بیشتری دارند. تبلیغات، محصولات و ترافیک آن‌ها را کنار هم بررسی کن.':guessed==='products'?'این سه محصول در سناریوی نمونه رشد بیشتری دارند. تبلیغ‌های مرتبط و پیام معرفی هر محصول می‌تواند نقطهٔ شروع مقایسه باشد.':'در سناریوی نمونه، تبلیغات زیر ROAS بالاتری دارند. قالب، پیام و محصول مرتبط آن‌ها را مقایسه کن.'}</div><div class="saved-report-list">${list.map(r=>`<button class="saved-report" data-open="${guessed}" data-id="${r.id}"><strong>${esc(r.name||r.title)}</strong><span class="pill good">${guessed==='ads'?'ROAS '+r.roas:'رشد '+num(r.growth)+'٪'} ${ico('arrow')}</span></button>`).join('')}</div><p class="dialog-hint">این پاسخ از داده‌ها و سناریوی آمادهٔ دمو ساخته شده است؛ پاسخ هوش مصنوعی زنده یا پژوهش واقعی نیست.</p><div class="dialog-actions"><button class="btn primary" data-action="navigate" data-value="${guessed}">بررسی همهٔ نتایج ${ico('arrow')}</button></div>`)}
function compare(){const list=D.ads.filter(a=>state.compared.includes(a.id));if(!list.length)return;openDialog('مقایسهٔ تبلیغات منتخب','پیام، عملکرد و محصول را کنار هم بررسی کن.',`<div class="table-wrap"><table><thead><tr><th>شاخص</th>${list.map(a=>`<th>${a.title}</th>`).join('')}</tr></thead><tbody>${[['فروشگاه',a=>shop(a.shop).name],['قالب',a=>a.format],['بازدید',a=>compact(a.reach)],['ROAS',a=>a.roas],['CTR',a=>a.ctr+'%'],['روز فعالیت',a=>num(a.active)]].map(([l,fn])=>`<tr><th>${l}</th>${list.map(a=>`<td>${fn(a)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="dialog-hint">تمام شاخص‌ها نمونه‌اند.</p>`,true)}
function exportCSV(){const p=['ads','products','shops'].includes(page)?page:page==='saved'?state.savedTab:page==='reports'?(state.reportType||'ads'):'ads',rows=page==='reports'?(p==='ads'?D.ads:p==='products'?D.products:shops()):page==='saved'?(p==='ads'?D.ads:p==='products'?D.products:shops()).filter(r=>saved(p,r.id)):filtered(p),cols=p==='ads'?[['عنوان','title'],['فروشگاه',r=>shop(r.shop).name],['رسانه','platform'],['روز فعالیت','active'],['بازدید','reach'],['ROAS','roas'],['CTR','ctr']]:p==='products'?[['محصول','name'],['فروشگاه',r=>shop(r.shop).name],['قیمت نمونه USD','price'],['تبلیغات فعال','active'],['رشد نمونه','growth']]:[['فروشگاه','name'],['دامنه','domain'],['درآمد روزانه تخمینی نمونه USD','revenue'],['بازدید ماهانه نمونه','visits'],['رشد نمونه','growth'],['تبلیغات فعال','active']];const lines=[cols.map(c=>c[0]),...rows.map(r=>cols.map(c=>typeof c[1]==='function'?c[1](r):r[c[1]]))];const csv='\uFEFF'+lines.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='NAMA-Analyze-'+p+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('خروجی داده‌های نمونه آماده شد.')}
function showMenu(el,html){menu.innerHTML=html;const r=el.getBoundingClientRect();menu.style.top=Math.min(r.bottom+7,innerHeight-180)+'px';menu.style.right=Math.max(12,innerWidth-r.right)+'px';menu.hidden=false}
function help(){openDialog('دموی Analyze را امتحان کن.','تمرکز این نسخه: شناخت بازار، تبلیغات، محصولات و فروشگاه‌ها.',`<div class="detail-copy">از Home شروع کن. در Ads رسانه، کشور یا دسته را فیلتر کن؛ یک تبلیغ را تحلیل و ذخیره کن. در Products، محصول و تبلیغات مرتبط را ببین. در Shops، رشد فروشگاه‌ها را مقایسه و یک فروشگاه را پیگیری کن. سپس یافته‌ها را در گزارش‌ها بررسی کن.</div><div class="dialog-actions">${act('شروع دوبارهٔ دمو','reset-confirm','btn')}<button class="btn primary" data-action="navigate" data-value="home">رفتن به Home</button></div><p class="dialog-hint">همهٔ داده‌ها نمونه‌اند و تغییرات فقط در این مرورگر ذخیره می‌شوند.</p>`)}
document.addEventListener('click',async e=>{
 const linked=e.target.closest('[data-shop-mode]');if(linked){e.preventDefault();state.shopMode=linked.dataset.shopMode;persist();navigate('shops');return}
 const link=e.target.closest('a[href^="#/"]');if(link){e.preventDefault();const href=link.getAttribute('href'),next=Object.keys(hashes).find(k=>hashes[k]===href);navigate(next||'home');return}
 const save=e.target.closest('[data-save]');if(save){toggleSave(save.dataset.save,save.dataset.id);return}
 const entity=e.target.closest('[data-open]');if(entity){openEntity(entity.dataset.open,entity.dataset.id);return}
 const tab=e.target.closest('[data-tab]');if(tab){if(tab.dataset.tab==='top')state.topTab=tab.dataset.value;else state.savedTab=tab.dataset.value;persist();render();return}
 const day=e.target.closest('[data-day]');if(day){state.day=+day.dataset.day;persist();render();return}
 const platformButton=e.target.closest('[data-platform]');if(platformButton){F('ads').platform=platformButton.dataset.platform;state.pagination.ads=1;persist();render();return}
 const view=e.target.closest('[data-view]');if(view){state.view[view.dataset.page]=view.dataset.view;persist();render();return}
 const clear=e.target.closest('[data-clear-filter]');if(clear){delete F(clear.dataset.page)[clear.dataset.clearFilter];state.pagination[clear.dataset.page]=1;persist();render();return}
 const pagination=e.target.closest('[data-pagination]');if(pagination){state.pagination[pagination.dataset.page]=(state.pagination[pagination.dataset.page]||1)+ +pagination.dataset.pagination;persist();render();$('#content').scrollIntoView();return}
 const el=e.target.closest('[data-action]');if(!el){if(!e.target.closest('#menu'))menu.hidden=true;return}const action=el.dataset.action,id=el.dataset.id;menu.hidden=true;
 if(action==='close-dialog'){dialog.close();return}
 if(action==='navigate'){if(dialog.open)dialog.close();navigate(el.dataset.value);return}
 if(['home','ads','products','shops','reports','saved'].includes(action)){navigate(action);return}
 if(action==='theme'){state.theme=state.theme==='dark'?'light':'dark';persist();render();return}
 if(action==='mobile-menu'){mobileMenu=!mobileMenu;render();return}
 if(action==='workspace'){workspaceDialog();return}
 if(action==='edit-brief'){if(dialog.open)dialog.close();navigate('start');return}
 if(action==='add-shop'){addShop();return}
 if(action==='new-report'){newReport();return}
 if(action==='open-report'){const r=state.reports.find(r=>String(r.id)===id);if(r){state.period=r.period;state.reportType=r.type;persist();navigate('reports');toast('گزارش «'+r.name+'» باز شد.')}return}
 if(action==='prompt'){askQuestion(el.textContent.trim(),el.dataset.value);return}
 if(action==='shop-mode'){state.shopMode=el.dataset.value;persist();render();return}
 if(action==='one-per-shop'){state.onePerShop=el.dataset.value==='one';state.pagination.products=1;persist();render();return}
 if(action==='clear-filters'){const p=el.dataset.page||page;state.filters[p]={};state.pagination[p]=1;if(p==='shops')state.shopMode='all';persist();render();return}
 if(action==='export'){exportCSV();return}
 if(action==='alert'){const index=state.alerts.indexOf(id);if(index>=0)state.alerts.splice(index,1);else state.alerts.push(id);persist();syncSaves();toast(index>=0?'اعلان نمایشی خاموش شد.':'پیگیری نمایشی روشن شد؛ اعلان واقعی ارسال نمی‌شود.');return}
 if(action==='notifications'){openDialog('اعلان‌های فضای تحلیل','وضعیت پیگیری‌های نمونه در همین مرورگر',`<div class="detail-copy">${state.alerts.length?fa(state.alerts.length)+' فروشگاه برای پیگیری انتخاب کرده‌ای. این نسخه اعلان زنده یا خودکار ارسال نمی‌کند.':'هنوز برای فروشگاهی پیگیری تغییرات را روشن نکرده‌ای. در صفحهٔ Shops، نشان زنگ را بزن.'}</div><div class="saved-report-list">${state.alerts.map(id=>`<button class="saved-report" data-open="shops" data-id="${id}">${esc(shop(id).name)} ${ico('arrow')}</button>`).join('')}</div>`);return}
 if(action==='profile-menu'){showMenu(el,act(ico('users')+'پروفایل پروژه','workspace')+act(ico('plus')+'شروع پروژه','edit-brief')+act(ico('file')+'راهنمای دمو','help')+act(ico('refresh')+'شروع دوبارهٔ دمو','reset-confirm'));return}
 if(action==='help'){help();return}
 if(action==='ad-menu'){showMenu(el,act(ico('eye')+'تحلیل تبلیغ','show-ad','',`data-id="${id}"`)+act(ico('copy')+'کپی متن تبلیغ','copy-ad','',`data-id="${id}"`)+act(ico('chart')+(state.compared.includes(id)?'برداشتن از مقایسه':'افزودن به مقایسه'),'toggle-compare','',`data-id="${id}"`));return}
 if(action==='show-ad'){adDetail(id);return}
 if(action==='copy-ad'){try{await navigator.clipboard.writeText(ad(id).copy);toast('متن تبلیغ کپی شد.')}catch{openDialog('متن تبلیغ','متن را انتخاب و کپی کن.',`<div class="form-field"><textarea readonly aria-label="متن تبلیغ برای کپی">${esc(ad(id).copy)}</textarea></div>`)}return}
 if(action==='toggle-compare'){const i=state.compared.indexOf(id);if(i>=0)state.compared.splice(i,1);else if(state.compared.length<3)state.compared.push(id);else{toast('برای مقایسه حداکثر سه تبلیغ انتخاب کن.');return}persist();render();return}
 if(action==='compare'){compare();return}
 if(action==='clear-compare'){state.compared=[];persist();render();return}
 if(action==='shop-ads'){const s=shop(id);state.filters.ads={query:s.name};state.pagination.ads=1;persist();dialog.close();navigate('ads');return}
 if(action==='reset-confirm'){openDialog('شروع دوبارهٔ دمو','فقط تغییرات نسخهٔ فعلی Analyze در همین مرورگر بازنشانی می‌شود.',`<p class="muted">ذخیره‌ها، فروشگاه‌های اضافه‌شده و گزارش‌های آزمایشی این نسخه پاک می‌شوند.</p><div class="dialog-actions">${act('انصراف','close-dialog','btn')}${act('بازنشانی دمو','reset','btn primary')}</div>`);return}
 if(action==='reset'){state=initial();window.NAMA_ENTRY.reset();persist();dialog.close();navigate('portal');toast('دموی Analyze به حالت اولیه برگشت.');return}
});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter){const p=el.dataset.page||page;F(p)[el.dataset.filter]=el.value;state.pagination[p]=1;persist();render();return}if(el.dataset.control==='sort'){state.sort[el.dataset.page]=el.value;state.pagination[el.dataset.page]=1;persist();render()}else if(el.dataset.control==='period'){state.period=+el.value;persist();render()}});
document.addEventListener('input',e=>{const el=e.target,p=el.dataset.query||(el.id==='headerQuery'?(['ads','products','shops'].includes(page)?page:'ads'):null);if(!p)return;F(p).query=el.value;state.pagination[p]=1;persist();if(el.id==='headerQuery'&&!['ads','products','shops'].includes(page))return;clearTimeout(filterTimer);const selector=el.id?'#'+el.id:'[data-query="'+p+'"]',caret=el.selectionStart;filterTimer=setTimeout(()=>{render();const input=$(selector);input?.focus({preventScroll:true});if(typeof caret==='number')input?.setSelectionRange(caret,caret)},220)});
document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const v=Object.fromEntries(new FormData(form));
 if(form.dataset.form==='ask'){const q=String(v.question||'').trim();if(q)askQuestion(q);return}
 if(form.dataset.form==='header-search'){const p=['ads','products','shops'].includes(page)?page:'ads';F(p).query=$('#headerQuery').value.trim();state.pagination[p]=1;persist();navigate(p);return}
 if(form.dataset.form==='workspace'){const name=String(v.name||'').trim();if(!name)return;state.workspace=name;persist();dialog.close();render();toast('نام فضای کاری ذخیره شد.');return}
 if(form.dataset.form==='add-shop'){const name=String(v.name||'').trim();let domain;try{const raw=String(v.domain||'').trim(),url=new URL(raw.includes('://')?raw:'https://'+raw);domain=url.hostname.toLowerCase();if(!domain.includes('.')||!name||!['https:','http:'].includes(url.protocol))throw Error();if(shops().some(s=>s.domain.toLowerCase()===domain)){$('#shopError').textContent='این دامنه قبلاً در فهرست اضافه شده است.';return}}catch{$('#shopError').textContent='یک نام و دامنهٔ معتبر مانند shop.example وارد کن.';return}const country=D.countries.includes(v.country)?v.country:D.countries[0],category=D.categories.includes(v.category)?v.category:D.categories[0],id='custom-'+Date.now();state.customShops.unshift({id,name,domain,initial:name.slice(0,1),color:'#f1e5e7',category,country,flag:({'کانادا':'🇨🇦','آمریکا':'🇺🇸','انگلستان':'🇬🇧','فرانسه':'🇫🇷','آلمان':'🇩🇪'})[country],revenue:null,visits:null,growth:null,active:0,total:0,products:0,created:new Date().toISOString().slice(0,10),media:[],trend:[],pending:true});state.saved.shops.push(id);state.filters.shops={};state.shopMode='all';state.pagination.shops=1;persist();dialog.close();navigate('shops');toast('فروشگاه به فهرست پیگیری همین دمو اضافه شد.');return}
 if(form.dataset.form==='new-report'){const name=String(v.name||'').trim();if(!name)return;state.reports.push({id:Date.now(),name,period:+v.period,type:v.type});state.period=+v.period;state.reportType=v.type;persist();dialog.close();navigate('reports');toast('تنظیمات گزارش نمونه ذخیره شد.');return}
});
dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.hidden=true;if(mobileMenu){mobileMenu=false;render()}}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#headerQuery')?.focus()}});
window.NAMA_ENTRY.init({render,navigate:hash=>{history.pushState(null,'',hash);readRoute();document.querySelector('#entryTitle')?.focus({preventScroll:true});},complete:brief=>{if(!state.projectBrief)state.workspace=brief.idea.includes('ورزشی')?'برند پوشاک ورزشی':brief.idea.includes('مینیمال')?'پوشاک مینیمال':'پروژهٔ من';state.projectBrief=brief;persist();navigate('home');document.querySelector('#content')?.focus({preventScroll:true});},sample:()=>navigate('home')});
let lastHash=location.hash;addEventListener('popstate',()=>{lastHash=location.hash;readRoute()});addEventListener('hashchange',()=>{if(location.hash!==lastHash){lastHash=location.hash;readRoute()}});
readRoute();
